      const controls = el('div', 'allen-pane-controls');
      const min = button('allen-pane-ctl allen-pane-min', '', '\u2212', () => minimize(rec));
      const max = button('allen-pane-ctl allen-pane-max', '', '\u25a1', () => maximize(rec));
