      controls.append(min, max, shut);
      head.append(move, el('span', 'allen-pane-kind', NAMES[kind]), heading, badge, controls);
      const notice = el('p', 'allen-pane-notice');
      notice.setAttribute('role', 'alert');
      notice.hidden = true;
      const body = el('div', 'allen-pane-body');
      body.tabIndex = 0;
      const source = el('details', 'allen-pane-source');
      source.hidden = true;
      const foot = el('div', 'allen-pane-foot');
      foot.hidden = true;
      const size = button('allen-pane-size', '', '', null);
      const grab = button('allen-pane-grab', '', '', () => minimize(rec));
